\shortans{0}

\loigiai{
$\sqrt{13-2\sqrt{12}}-\dfrac{11}{\sqrt{12}-1}+2=\sqrt{(\sqrt{12}-1)^2}- \dfrac{11}{\sqrt{12}-1}+2$\\
$=\sqrt{12}-1-(\sqrt{12}+1)+2=-2.1+2=0$.
}\end{ex}

\begin{ex}%[9D3H1-3]
Rút gọn biểu thức $\sqrt{6-2\sqrt{5}}-\dfrac{4}{\sqrt{5}-1}-10$ ta được kết quả là

\shortans{-12}

\loigiai{
$\sqrt{6-2\sqrt{5}}-\dfrac{4}{\sqrt{5}-1}-10=\sqrt{(\sqrt{5}-1)^2}- \dfrac{4}{\sqrt{5}-1}-10$\\
$=\sqrt{5}-1-(\sqrt{5}+1)-10=-2.1-10=-12$.
}\end{ex}
